import { INTERNAL_LIMITS as limits, jsonBytes } from "./budgets";

export const admissionSchema = z.object({ infrastructureId: z.uuid(), idempotencyKey: z.string().regex(/^[A-Za-z0-9_-]{1,80}$/),
  expectedDesignUpdatedAt: z.iso.datetime(), workload: WorkloadProfileSchema.extend({ readWriteRatio: z.number().min(0).max(1) }).strict(), contract: z.unknown() }).strict();
export class CompilationRefusal extends Error { constructor(readonly diagnostics: Diagnostic[]) { super("Internal Model-2 contract refused"); } }
export interface ExecutionEnvelope {
  schema: "infraforge-internal-execution/1"; runId: string; ownerId: string; infrastructureId: string; designUpdatedAt: string;
  source: string; design: SavedProductDesign; contract: ProductContract; compiled: CompiledProduct; compiledHash: string; metering: MeteringConfig; fingerprint: string;
}
function refusal(code: string, path: string, message: string): never { throw new CompilationRefusal([{ code, path, message, severity: "error" }]); }
export function compileEnvelope(runId: string, ownerId: string, layout: unknown, updatedAt: Date, request: z.infer<typeof admissionSchema>): ExecutionEnvelope {
  try { boundedProduct(request); jsonBytes(request, limits.requestBytes); }
  catch (error) { refusal("INPUT_BUDGET", "contract", error instanceof Error ? error.message : "Input budget exceeded"); }
  try { boundedProduct(layout); jsonBytes(layout, limits.requestBytes); }
  catch { refusal("SAVED_DESIGN_BUDGET", "design", "Saved layout exceeds the internal structural/text/byte budget"); }
  // JSONB does not preserve object-key order. Compile the canonical authored
  // contract so provenance traversal reconstructs identically after persistence.
  const parsed = LayoutSchema.safeParse(layout);
  if (!parsed.success) refusal("SAVED_DESIGN_INVALID", "design", "Saved infrastructure layout is invalid");
  const saved = parsed.data, contract = canonical(request.contract) as ProductContract;
  if (!contract || typeof contract !== "object") refusal("CONTRACT_REQUIRED", "contract", "Supply a complete versioned application/infrastructure contract");
  if (contract.capabilities?.length) refusal("PROVIDER_SCOPE", "contract.capabilities", "Provider capability/price bindings are excluded from this authored internal slice");
  const objectNode = saved.resources.find((r) => r.type === "Object Storage"), objectConfig = objectNode && contract.nodes?.[objectNode.id]?.resources?.[0]?.config;
  if (objectConfig?.kind === "object-store" && objectConfig.capacity === undefined) refusal("CAPACITY_REQUIRED", "contract.nodes", "Object storage requires an explicit authored byte capacity");
  const design: SavedProductDesign = { schema: "infraforge-saved-design/1", resources: saved.resources, connections: saved.connectionLines, workload: request.workload };
  if (design.resources.length !== 2 || design.resources.filter((r) => r.type === "Virtual Machine").length !== 1 || design.resources.filter((r) => r.type === "Object Storage").length !== 1)
    refusal("INTERNAL_SCOPE", "resources", "This internal slice requires exactly one Virtual Machine and one Object Storage node; other resource compositions are refused");
  for (const r of design.resources) if (["skuId", "size", "region", "public", "encryption", "openPorts", "autoscaling"].some((key) => key in r)) refusal("UNSUPPORTED_CONTROL", `resources.${r.id}`, "SKU, region, legacy security, size and autoscaling controls are outside this internal scope; supply explicit authored resource/listener contracts");
  if (!contract.limits || contract.limits.maxEvents > limits.events || contract.limits.maxRequests > limits.requests || contract.limits.maxSamples > limits.samples || contract.limits.maxRawResults > limits.requests || contract.limits.maxTraceRows > limits.requests)
    refusal("EXECUTION_BUDGET", "contract.limits", "Explicit bounded limits are required: events ≤10000, requests/raw/trace ≤256, samples ≤64");
  if (!Array.isArray(contract.commands) || contract.commands.length > limits.commands || !Array.isArray(contract.faults) || contract.faults.length > 1 || contract.faults.some((f) => f.kind !== "Crash" || f.profile !== "retain-logical-state/1" || !design.resources.some((r) => r.id === f.target && r.type === "Object Storage")))
    refusal("SCHEDULE_SCOPE", "contract", "At most 16 recorded commands and one retained-logical-object crash are supported; other faults are refused");
  const compiled = compileProduct(design, contract);
  if (!compiled.ok) throw new CompilationRefusal(compiled.diagnostics);
  const horizon = requireKnown(contract.horizon, "us");
  if (horizon > limits.horizonUs || compiled.value.input.resources.length !== 2 || compiled.value.pools.length || compiled.value.input.paths.length > 4 || compiled.value.input.links.length > 8)
    refusal("MATERIALIZED_SCOPE", "compiled", "Bounded two-station internal execution required; horizon ≤1000000 us, no pool/auxiliary expansion");
  const vm = design.resources.find((r) => r.type === "Virtual Machine")!, objects = design.resources.find((r) => r.type === "Object Storage")!;
  if (compiled.value.input.operations.some((o) => o.entry !== vm.id) || compiled.value.input.resources.some((r) => r.kind === "compute" && r.downstream) || compiled.value.input.systems.commands.some((c) => c.source !== vm.id || c.target !== objects.id))
    refusal("APPLICATION_SCOPE", "contract", "This slice runs standalone VM application CPU and separate recorded VM-to-object commands; other application mappings are refused");
  const compiledHash = contentHash(compiled.value);
  const metering: MeteringConfig = { schema: "infraforge-usage-metering/1", run: runId, epoch: "execution-1", inputFingerprint: compiledHash,
    provenance: ["Internal product run: actual modeled commands, current objects and directed payload; no physical/cloud billing claim"],
    objects: compiled.value.input.resources.filter((r) => r.kind === "object-store").map((r) => r.id), links: compiled.value.input.links.map((l) => l.id),
    maxRecords: limits.records, maxFields: limits.fields, maxTextCharacters: limits.textCharacters };
  const body = { schema: "infraforge-internal-execution/1" as const, runId, ownerId, infrastructureId: request.infrastructureId, designUpdatedAt: updatedAt.toISOString(), source: executionSource, design, contract, compiled: compiled.value, compiledHash, metering };
  const envelope = canonical({ ...body, fingerprint: contentHash(body) }); captureCuts(envelope);
  try { jsonBytes(envelope, limits.inputBytes); } catch { refusal("PERSISTENCE_BUDGET", "envelope", "Compiled execution envelope exceeds the internal persistence budget"); }
  return envelope;
}
export function readEnvelope(value: unknown, expected: string, compatible = true): ExecutionEnvelope {
  boundedProduct(value); jsonBytes(value, limits.inputBytes);
  const envelope = canonical(value) as ExecutionEnvelope, { fingerprint, ...body } = envelope;
  if (fingerprint !== expected || contentHash(body) !== fingerprint) throw Error("Recorded input content is missing or corrupt");
  if (envelope.schema !== "infraforge-internal-execution/1") throw Error("Unsupported historical input version; no reinterpretation");
  if (compatible && envelope.source !== executionSource) throw Error("Historical execution source is incompatible with this runtime");
  if (compatible) {
    const current = compileProduct(envelope.design, envelope.contract);
    if (!current.ok || contentHash(current.value) !== envelope.compiledHash || contentHash(envelope.compiled) !== envelope.compiledHash) throw Error("Historical compilation is incompatible or corrupt");
  }
  return envelope;
}
export function captureCuts(envelope: ExecutionEnvelope) {
  const horizon = requireKnown(envelope.contract.horizon, "us"), cuts = new Set([0, horizon]);
  for (let i = 1; i < 16; i++) cuts.add(Math.ceil(horizon * i / 16));
  for (const f of envelope.contract.faults) { const at = requireKnown(f.at, "us"), end = at + requireKnown(f.duration, "us"); cuts.add(at); cuts.add(end); cuts.add(end + requireKnown(f.restart!, "us")); }
  const ordered = [...cuts].filter((at) => at <= horizon).sort((a, b) => a - b);
  if (ordered.length > limits.captures) throw Error("Capture budget exceeded"); return ordered;
}

import { randomUUID } from "node:crypto";
import type { WorkerOwnership } from "../infra/workerOwnership";
import type { InternalRunRow } from "./store";
import { readEnvelope, captureCuts } from "./envelope";
import { capture, instantiate } from "./capture";
import type { StoredCapture, CaptureCheckpoint } from "./capture";
import { lessonRecord } from "./lessonStore";
import { executeLesson } from "./lessonExecution";
export async function retireInternalRuns(ownership: WorkerOwnership) {
  await ownership.transaction(async (db) => {
    await db.query(`UPDATE "InternalModel2Run" SET status='interrupted',reason='Worker restarted; last durable prefix retained. Exact continuation is unsupported.',"updatedAt"=now() WHERE status='running'`);
    await db.query(`UPDATE "InternalModel2Run" r SET status='failed',reason='Durable queue delivery exhausted before execution',"updatedAt"=now()
      WHERE status='queued' AND EXISTS (SELECT 1 FROM "Outbox" o WHERE o."eventType"='model2-internal-created' AND o.status='failed' AND o.payload->>'internalModel2RunId'=r.id)`);
  });
}
export async function failInternalDelivery(ownership: WorkerOwnership, id: string) {
  await ownership.transaction(async (db) => { await db.query(`UPDATE "InternalModel2Run" SET status='failed',reason='Durable queue delivery exhausted before execution',"updatedAt"=now() WHERE id=$1 AND status='queued'`, [id]); });
}
export async function executeInternalRun(id: string, ownership: WorkerOwnership) {
  if (await lessonRecord(id)) { await executeLesson(id, ownership); return; }
  const claimed = await ownership.transaction(async (db) => {
    const row = (await db.query<InternalRunRow>('SELECT * FROM "InternalModel2Run" WHERE id=$1 FOR UPDATE', [id])).rows[0];
    if (!row || !["queued", "running"].includes(row.status)) return null;
    if (row.status === "running") { await db.query(`UPDATE "InternalModel2Run" SET status='interrupted',reason='Prior delivery stopped without a terminal commit; no resume',"updatedAt"=now() WHERE id=$1`, [id]); return null; }
    try {
      if (!(await db.query('SELECT 1 FROM "InternalModel2Grant" WHERE "userId"=$1 AND scope=\'operator\'', [row.ownerId])).rowCount) throw Error("Internal authorization revoked before execution");
      const input = readEnvelope(row.input, row.inputHash);
      if (input.runId !== row.id || input.ownerId !== row.ownerId) throw Error("Recorded execution owner/identity mismatch");
      const token = randomUUID();
      await db.query('UPDATE "InternalModel2Run" SET status=\'running\',token=$2,"updatedAt"=now() WHERE id=$1', [id, token]);
      return { input, token };
    } catch (error) {
      await db.query('UPDATE "InternalModel2Run" SET status=\'failed\',reason=$2,"updatedAt"=now() WHERE id=$1', [id, message(error)]); return null;
    }
  });
  if (!claimed) return;
  let sequence = 0;
  let history: CaptureCheckpoint[] = [];
  const stop = async (reason: string) => ownership.transaction(async (db) => {
    await db.query('UPDATE "InternalModel2Run" SET status=\'interrupted\',reason=$3,"updatedAt"=now() WHERE id=$1 AND token=$2 AND status=\'running\'', [id, claimed.token, reason.slice(0, 500)]);
  });
  async function persist(value: StoredCapture, final: boolean, failure: string | null) {
    return ownership.transaction(async (db) => {
      const row = (await db.query<InternalRunRow>('SELECT * FROM "InternalModel2Run" WHERE id=$1 AND token=$2 AND status=\'running\' FOR UPDATE', [id, claimed!.token])).rows[0];
      if (!row) return false;
      if (row.sequence !== sequence) throw Error("Durable capture sequence changed");
      const granted = (await db.query('SELECT 1 FROM "InternalModel2Grant" WHERE "userId"=$1 AND scope=\'operator\'', [row.ownerId])).rowCount;
      const cancelled = row.cancelRequested || !granted, status = cancelled ? "cancelled" : failure ? "failed" : final ? "completed" : "running";
      const reason = !granted ? "Internal authorization revoked; stopped at the next capture boundary" : row.cancelRequested ? "Cancellation requested; stopped at the next capture boundary" : failure;
      await db.query('UPDATE "InternalModel2Run" SET status=$3,evidence=$4,sequence=$5,"throughUs"=$6,reason=$7,"updatedAt"=now() WHERE id=$1 AND token=$2 AND status=\'running\'', [id, claimed!.token, status, value, value.sequence, value.throughUs, reason]);
      sequence = value.sequence; return status === "running";
    });
  }
  try {
    const runtime = instantiate(claimed.input), cuts = captureCuts(claimed.input);
    for (const at of cuts) {
      await ownership.assertHeld();
      let failure: string | null = null;
      try { runtime.advanceTo(at); } catch (error) { failure = message(error); }
      const value = capture(runtime, claimed.input, sequence + 1, history);
      if (!await persist(value, at === runtime.horizon, failure)) return;
      history = value.checkpoints;
    }
  } catch (error) {
    // Advanced work whose capture did not commit is never replayed as continuation.
    // If this write also fails, startup/re-delivery will retire the running row.
    await stop(`Execution/persistence interrupted: ${message(error)}; last durable prefix retained`);
  }
}
const message = (error: unknown) => (error instanceof Error ? error.message : "Internal execution failed").slice(0, 400);

import { createHash } from "node:crypto";
import { readdirSync, readFileSync } from "node:fs";
import { relative, resolve } from "node:path";
import { canonical } from "@infraforge/simulation/internal-product";
export const hasher = { algorithm: "sha256-utf8/1" as const, hash: (text: string) => createHash("sha256").update(text).digest("hex") };
export const contentHash = (value: unknown) => hasher.hash(JSON.stringify(canonical(value)));
const root = resolve(import.meta.dir, "../../..");
function sourceIdentity() {
  const walk = (dir: string): string[] => readdirSync(dir, { withFileTypes: true }).flatMap((e) => e.isDirectory() ? walk(resolve(dir, e.name)) : e.name.endsWith(".ts") ? [resolve(dir, e.name)] : []);
  const folders = ["packages/simulation/src/model2", "packages/simulation/src/reality", "packages/domain/src", "packages/catalog/src"];
  const paths = [...folders.flatMap((p) => walk(resolve(root, p))), ...["packages/simulation/src/internalProduct.ts", ...["identity", "envelope", "budgets", "capture"].map((p) => `apps/backend/internalModel2/${p}.ts`)].map((p) => resolve(root, p))]
    .map((p) => relative(root, p).replaceAll("\\", "/")).sort();
  const files = [...paths, "bun.lock", "apps/backend/zod_schemas/layout.schema.ts", "apps/backend/zod_schemas/deployment.schema.ts"].sort();
  return contentHash({ runtime: `bun-${Bun.version}`, files: files.map((p) => [p, readFileSync(resolve(root, p), "utf8").replaceAll("\r\n", "\n")]) });
}
// Frozen with this process/image; changing execution source requires a new process.
export const executionSource = sourceIdentity();

import { randomUUID } from "node:crypto";
import { authoringGroups } from "@infraforge/contracts/internal-model2";
import { LESSON_VERSION } from "@infraforge/contracts/internal-lessons";
import type { LessonChoice, LessonReview } from "@infraforge/contracts/internal-lessons";
import { restartLesson } from "@infraforge/contracts/internal-lessons/profile";
import { assessDesign, authoredAssumptions, authoredContract } from "./authoring";
import { admissionSchema, compileEnvelope } from "./envelope";
import { contentHash } from "./identity";
import { LESSON_SANDBOX, lessonImage } from "./lessonLimits";
import { ConflictError, NotFoundError, ValidationError } from "../utils/errors";
import { internalDatabase } from "./store";
export const lessonLayout = { resources: [
  { id: "lesson-vm", type: "Virtual Machine", name: "Application", x: 0, y: 0 },
  { id: "lesson-objects", type: "Object Storage", name: "Current objects", x: 200, y: 0 },
], connectionLines: [{ id: "lesson-link", sourceId: "lesson-vm", targetId: "lesson-objects", sourceType: "Virtual Machine", targetType: "Object Storage", port: 8080 }] };
function assessLessonDesign(row: Parameters<typeof assessDesign>[0]) {
  const design = assessDesign(row);
  if (!design.supported) return design;
  const layout = row.layout as typeof lessonLayout;
  const check = (value: object, keys: string[], path: string) => {
    for (const key of Object.keys(value)) if (!keys.includes(key)) design.reasons.push(`Unmodeled saved setting ${path}.${key}; select a separate lesson design. No saved fields were removed.`);
  };
  check(layout, ["resources", "connectionLines", "layoutVersion"], "layout");
  for (const resource of layout.resources) check(resource, ["id", "type", "name", "x", "y"], resource.id);
  for (const connection of layout.connectionLines) check(connection, ["id", "sourceId", "targetId", "sourceType", "targetType", "port"], connection.id);
  if (design.port !== 8080) design.reasons.push("This lesson profile requires an explicit port 8080 connection.");
  design.supported = design.reasons.length === 0; return design;
}
export async function lessonDesigns(owner: string) {
  const rows = await internalDatabase.query('SELECT id,name,layout,"updatedAt" AT TIME ZONE \'UTC\' AS "updatedAt","challengeId" FROM "Infrastructure" WHERE "ownerId"=$1 ORDER BY "updatedAt" DESC LIMIT 100', [owner]);
  return rows.rows.map(assessLessonDesign);
}
export async function createLessonDesign(owner: string) {
  // One explicit, idempotent new design per owner. Never rewrite a saved layout.
  const hex = contentHash(`m2m-design/1:${owner}`), id = `${hex.slice(0,8)}-${hex.slice(8,12)}-4${hex.slice(13,16)}-a${hex.slice(17,20)}-${hex.slice(20,32)}`;
  await internalDatabase.query(`INSERT INTO "Infrastructure" (id,"userId","ownerId",name,layout,"updatedAt")
    VALUES ($1,$2,$2,'Object restart lesson',$3,now()) ON CONFLICT (id) DO NOTHING`, [id, owner, lessonLayout]);
  const row = (await internalDatabase.query('SELECT "ownerId",layout FROM "Infrastructure" WHERE id=$1', [id])).rows[0];
  if (row?.ownerId !== owner || contentHash(row.layout) !== contentHash(lessonLayout)) throw new ConflictError("The lesson design has changed. Select a supported saved design; no fields were overwritten.");
  return id;
}
export async function reviewLesson(owner: string, choice: LessonChoice): Promise<LessonReview> {
  const image = lessonImage();
